// Realistic characters generated by tools/humans.py from the CC0 MakeHuman base mesh:
// real hands with fingers, faces, body shapes, clothing shells — skinned to the mocap skeleton.
import * as THREE from 'three';
import { clothMaterial, skinDetail } from './caricatures.js';

const BASE = new URL('../vendor/models/humans/', import.meta.url).href;
const assets = new Map();

export function loadHuman(arch) {
  if (assets.has(arch)) return assets.get(arch);
  const p = (async () => {
    const [h, bin] = await Promise.all([
      fetch(`${BASE}${arch}.json`).then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); }),
      fetch(`${BASE}${arch}.bin`).then((r) => { if (!r.ok) throw new Error(r.status); return r.arrayBuffer(); }),
    ]);
    const skinTex = await new THREE.TextureLoader().loadAsync(BASE + h.skin);
    skinTex.colorSpace = THREE.SRGBColorSpace; skinTex.anisotropy = 4; skinTex.flipY = true;
    const geos = h.prims.map((p) => {
      const g = new THREE.BufferGeometry();
      const ip = new Int16Array(bin, p.pos, p.count * 3), fp = new Float32Array(p.count * 3);
      for (let i = 0; i < fp.length; i++) fp[i] = ip[i] * h.posScale;
      g.setAttribute('position', new THREE.BufferAttribute(fp, 3));
      g.setAttribute('normal', new THREE.BufferAttribute(new Int16Array(bin, p.nrm, p.count * 3), 3, true));
      g.setAttribute('uv', new THREE.BufferAttribute(new Uint16Array(bin, p.uv, p.count * 2), 2, true));
      g.setAttribute('skinIndex', new THREE.BufferAttribute(new Uint8Array(bin, p.si, p.count * 4), 4));
      g.setAttribute('skinWeight', new THREE.BufferAttribute(new Uint8Array(bin, p.sw, p.count * 4), 4, true));
      g.setIndex(new THREE.BufferAttribute(p.index32 ? new Uint32Array(bin, p.idx, p.indexCount) : new Uint16Array(bin, p.idx, p.indexCount), 1));
      g.computeBoundingSphere();
      return g;
    });
    const a = { h, geos, skinTex };
    a.mats = h.prims.map((p) => materialFor(p.mat, a));
    return a;
  })().catch(() => null);
  assets.set(arch, p);
  return p;
}
export const humanAsset = (arch) => assets.get(arch);

function materialFor(m, a) {
  if (m.kind === 'skinatlas') {
    const mat = new THREE.MeshPhysicalMaterial({ map: a.skinTex, roughness: 1, sheen: 0.15, sheenRoughness: 0.45, sheenColor: new THREE.Color('#ffb59c') });
    skinDetail(mat);
    mat.emissive = new THREE.Color('#2a0a04'); mat.emissiveIntensity = 0.25; // shadows go warm like real skin
    return mat;
  }
  if (m.kind === 'eye') { const t = new THREE.TextureLoader().load(BASE + m.tex); t.colorSpace = THREE.SRGBColorSpace; return new THREE.MeshPhysicalMaterial({ map: t, roughness: 0.25, clearcoat: 1, clearcoatRoughness: 0.05 }); }
  if (m.kind === 'lash') return new THREE.MeshStandardMaterial({ color: '#1a120c', roughness: 0.9 });
  if (m.kind === 'rubber') return new THREE.MeshStandardMaterial({ color: m.color, roughness: 0.4 });
  return clothMaterial(m.kind, m.color);
}

/** Dress a cloned mocap skeleton with a generated human. Returns the meshes (for hit flashes). */
export function attachHuman(model, a) {
  const byName = {};
  model.traverse((o) => { if (o.isBone) byName[o.name.replace(/^mixamorig/, '')] = o; });
  for (const [n, p] of Object.entries(a.h.bones)) if (byName[n]) byName[n].position.set(p[0], p[1], p[2]);
  // bodies are built with the mocap's hip height; scale the whole rig (animation included) to the character's real height
  const mt = a.h.metrics;
  if (mt.height) model.scale.multiplyScalar(mt.height / (mt.headTop[1] * model.scale.y));
  model.updateMatrixWorld(true);
  const skel = new THREE.Skeleton(a.h.skinBones.map((n) => byName[n]));
  const root = byName.Hips.parent;
  const meshes = a.geos.map((g, i) => {
    const m = new THREE.SkinnedMesh(g, a.mats[i]);
    m.castShadow = true; m.frustumCulled = false;
    root.add(m); m.updateMatrixWorld(true);
    m.bind(skel, m.matrixWorld);
    return m;
  });
  return meshes;
}
